// Project-aspect standard pack: the self-growing product research wiki
// (compile-once/refine-in-place, cited, dated, isolated behind the reviewed
// product-requirements crossing point). The folder is the classifier: the two
// reserved names (product-requirements/, sample-data/) have fixed meaning;
// everything else under product-wiki/ is wiki space. Fingerprinted by the
// standard's one structural constant — the sink.
import { SINK_README } from './lib.mjs';
import layout from './layout.mjs';
import pageSections from './page-sections.mjs';
import keyInsights from './key-insights.mjs';
import growthLog from './growth-log.mjs';
import sources from './sources.mjs';
import freshness from './freshness.mjs';
import isolation from './isolation.mjs';

export default {
  id: 'product-wiki',
  version: 1,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'agent-maintained market, user and competitor research wikis — cited pages, growth logs, the reviewed product-requirements sink',
    excludes: 'how the product is built or specced — that is spec-driven-product; requirement proofs are executable-requirements',
  },
  badge: 'badge.svg',
  marker: SINK_README,
  detect: (ctx) => ctx.tracked.includes(SINK_README),
  prose: 'RULES.md',
  // The isolation wall rides the barriers mechanism: this pack requires
  // barriers and CONTRIBUTES the fixed barrier as manifest data
  // (isolation.mjs — pure data, no cross-pack import; pack-independence).
  requires: ['barriers'],
  contributes: { barriers: [isolation] },
  // Adoption interview: the standard takes no config (the layout IS the config),
  // but a wiki with no research scope is a hollow skeleton — the answers frame
  // WHICH wikis get seeded and what the competitor set is measured against. They
  // record as intent on the entry (`answers`), never as config. Read the repo's
  // own product brief/spec first and confirm, rather than re-asking cold.
  questions: [
    {
      id: 'product',
      prompt: "What is the product — what does it do, and what is the core value it delivers? If the repo already carries a product brief or spec, read it and confirm rather than asking cold.",
      distill: 'recorded as intent on this entry (the pack takes no config); it names what the research is about and frames every seeded wiki',
    },
    {
      id: 'users',
      prompt: 'Who are the users or customers — the segments whose needs the research must track?',
      distill: 'recorded as intent; scopes the user-research wiki and whose problems the findings answer to',
    },
    {
      id: 'market',
      prompt: 'What market or category is this in, and who are the main competitors or alternatives? This is what the competitor research is scoped against.',
      distill: 'recorded as intent; names the competitor set the initial competitor-landscape wiki is seeded from',
    },
  ],
  worldRules: [layout, pageSections, keyInsights, growthLog, sources, freshness],
  // The pack's scheduled task — wiki-growth, the weekly research pass — lives in
  // this pack's `tasks/wiki-growth/`, discovered by the scheduler's filesystem
  // scan (engine/scheduler/discover.mjs), not declared here.
};
=== chrome-extension-release ===
import { workflowFiles } from '../../engine/checks/helpers/github-workflows.mjs';
import releaseWorkflows, { STUB_NAME, LEGACY_STUB_NAMES, LEGACY_CREATE_PACKAGE, VENDORED_CREATE_PACKAGE } from './release-workflows.mjs';
import templateTokens from './template-tokens.mjs';
import releaseConfig from './release-config.mjs';
import versionSync from './version-sync.mjs';
import releaseLayout from './release-layout.mjs';
import privacyPermissionAlignment from './privacy-permission-alignment.mjs';
import permissionAddedStoreIssue from './permission-added-store-issue.mjs';
import readmeSections from './readme-sections.mjs';

// A repo "ships the release pipeline" once it carries the orchestrator — a
// workflow named "Release to Chrome Store" that wires the create-package reusable
// — the fingerprint DESIGN.md pins the conformance suite to. A manifest alone
// never trips this, so coding an extension doesn't drag in the release checks;
// opting in — declaring the pack, then vendoring the release set (orchestrator +
// reusable workflows + composite actions), PRIVACY.md and the first-publication
// issue — does. Both halves matter: the orchestrator name is the consumer marker
// (Claudinite's OWN core workflows are named "Chrome extension: … (reusable)", so
// the name check keeps the canon repo from self-matching), and the create-package
// wiring proves it's a live pipeline. Either wiring form counts — the pre-
// vendoring canon call @main, or the vendored local file — so a consumer mid-
// migration (or fully vendored) both fingerprint. Legacy stub names still
// fingerprint, so a repo whose orchestrator predates a rename keeps its
// declaration honest while cer/release-workflows flags the stale name.
const STUB_NAMES = new Set([STUB_NAME, ...LEGACY_STUB_NAMES]);

function shipsReleasePipeline(ctx) {
  return workflowFiles(ctx).some((wf) => {
    const text = ctx.read(wf);
    if (text === null) return false;
    const name = /^name:\s*['"]?(.+?)['"]?\s*$/m.exec(text)?.[1];
    if (!STUB_NAMES.has(name)) return false;
    // Wires create-package either way: the pre-vendoring canon call @main, or the
    // vendored local file.
    return text.includes(`/.github/workflows/${LEGACY_CREATE_PACKAGE}@`) ||
      text.includes(`/Claudinite/.github/workflows/${LEGACY_CREATE_PACKAGE}`) ||
      text.includes(`./.github/workflows/${VENDORED_CREATE_PACKAGE}`);
  });
}

export default {
  id: 'chrome-extension-release',
  version: 1,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'store publication for a Chrome extension: release workflows, package versioning, release config, privacy and permission disclosure',
    excludes: 'extension coding and MV3 runtime gotchas — chrome-extension; generic workflow lint rules — github-actions',
  },
  badge: 'badge.svg',
  marker: 'the "Release to Chrome Store" orchestrator (wires the vendored reusable workflows + composite actions)',
  detect: shipsReleasePipeline,
  // The release standard builds on the coding pack — shipping presumes the MV3
  // rules that produced the extension.
  requires: ['chrome-extension'],
  // RELEASE.md is the on-demand reference (linked from the coding pack's RULES
  // and from findings), not always-on prose: it is long, and only the checks
  // need to be eager.
  prose: null,
  worldRules: [
    releaseWorkflows,
    templateTokens,
    releaseConfig,
    versionSync,
    releaseLayout,
    privacyPermissionAlignment,
    readmeSections,
  ],
  // Judges the change: a permission added in THIS diff needs its store issue.
  workRules: [permissionAddedStoreIssue],
  // Pack-contributed scheduled task: `tasks/store-release/` — the scheduler's
  // filesystem scan (engine/scheduler/discover.mjs) picks it up only on repos that
  // declare chrome-extension-release, so it is not declared here.
};
=== github-actions ===
import secretsInJobIf from './secrets-in-job-if.mjs';
import runPipefail from './run-pipefail.mjs';
import checkoutSubmodules from './checkout-submodules.mjs';
import scheduledFailureEscalation from './scheduled-failure-escalation.mjs';
import labelCreateBeforeAdd from './label-create-before-add.mjs';
import uniqueAutomationBranch from './unique-automation-branch.mjs';
import pagesArtifactSymlinks from './pages-artifact-symlinks.mjs';
import noScheduledFleetExecutor from './no-scheduled-fleet-executor.mjs';

export default {
  id: 'github-actions',
  version: 1,
  minEngineVersion: 1,
  ruleRoutingGuidance: {
    belongs: 'workflow YAML and Actions runner platform behaviour: triggers, secrets, permissions, scheduling, artifacts, reusable workflows and their pitfalls',
    excludes: 'git and GitHub command procedure — git-github; release pipeline content for one product — its release pack',
  },
  badge: 'badge.svg',
  marker: '.github/workflows/*.ya?ml',
  detect: (ctx) => ctx.tracked.some((f) => /^\.github\/workflows\/.+\.ya?ml$/.test(f)),
  prose: null,
  worldRules: [
    secretsInJobIf,
    runPipefail,
    checkoutSubmodules,
    scheduledFailureEscalation,
    labelCreateBeforeAdd,
    uniqueAutomationBranch,
    pagesArtifactSymlinks,
    noScheduledFleetExecutor,
  ],
  skills: ['github-actions-scheduling'],
};

