import { patternRule } from '../../engine/checks/helpers/pattern-rules.mjs';
import { WIKI_PAGE, WIKI_RESERVED } from './lib.mjs';

export default patternRule({
  id: 'product-wiki-key-insights',
  severity: 'blocking',
  doc: 'packs/product-wiki/README.md',
  description: 'Every wiki page opens with a succinct bulleted Key insights header',
  why: 'a research page whose findings can only be recovered by reading it end to end does not get read — the header is what makes a compiled wiki usable to a human',
  scanFiles: WIKI_PAGE,
  excludeFiles: WIKI_RESERVED,
  checkSections: [{
    section: 'Key insights',
    requireFirstOnPage: {
      what: 'the page opens with "## {first}", not its "## Key insights" header',
      fix: 'move "## Key insights" above every other section — a header a reader reaches after the body is not a header',
    },
    forbidProseLines: {
      what: 'prose in the Key insights header: "{line}"',
      fix: 'the header is a bulleted list only — make it a bullet or move it into the page body below the "## Key insights" section',
    },
    maxBulletBlockLength: {
      characters: 140,
      what: 'Key insights bullet runs {characters} characters (max 140): "{bullet}…"',
      fix: 'cut it to the finding in plain words — the qualifiers, the supporting detail and the citation all live in the page body',
    },
    minBullets: {
      count: 1,
      what: 'Key insights header carries no bullets',
      fix: 'open the page with "## Key insights" — up to 7 bullets, each one finding stated plainly in a line (max 140 characters), together enough for a reader to understand what the research found without reading the body',
    },
    maxBullets: {
      count: 7,
      what: 'Key insights header carries {bullets} bullets (max 7) — it has grown into a second body',
      fix: 'keep the 7 that matter most; the rest is what the page body is for',
    },
  }],
});
=====FILE packs/product-wiki/freshness.mjs
import { patternRule } from '../../engine/checks/helpers/pattern-rules.mjs';
import { WIKI_PAGE, WIKI_RESERVED } from './lib.mjs';

export default patternRule({
  id: 'product-wiki-freshness',
  severity: 'advisory',
  doc: 'packs/product-wiki/README.md',
  description: 'A wiki page whose newest Growth log entry is older than 45 days needs a growth pass',
  why: "a wiki that stopped growing silently stops being true — staleness must reach a human even when the unattended growth channel isn't firing",
  relevantWhen: { scanningWholeRepo: true },
  scanFiles: WIKI_PAGE,
  excludeFiles: WIKI_RESERVED,
  checkSections: [{
    section: 'Growth log',
    newestDatedBulletWithinDays: {
      days: 45,
      what: 'newest Growth log entry is {age} days old ({date}) — past the {days}-day freshness window',
      fix: 'run a product-wiki growth pass (in-session: "grow the product wiki"; method: the canon\'s packs/product-wiki/tasks/wiki-growth/task.md, mounted under .claudinite/ in consumers), or confirm this repo\'s scheduler workflow is wired and the wiki-growth task is on its schedule; silence via rules: {"product-wiki-freshness": "off"}',
    },
  }],
});
=====FILE packs/product-wiki/lib.mjs
import { finding } from '../../engine/checks/helpers/findings.mjs';

// The standard's path constants and the wiki-page classifier — spelled ONCE
// here so the checks, the manifest, and the barrier can't drift apart. The wiki
// set is STRUCTURAL, not configured: a wiki page is a README.md at depth >= 2
// under product-wiki/, outside the two reserved subtrees (product-requirements/
// — the human-reviewed sink — and sample-data/ — illustrative assets). No wikis
// manifest exists anywhere, so a renamed or newly added wiki folder is
// classified correctly with nothing to drift (folder-is-the-classifier).
// The section/bullet/date grammar the page checks assert lives in the
// declarative engine (engine/checks/helpers/pattern-rules.mjs, checkSections) —
// one grammar there, so the checks that share it can never disagree about it.
export const PRODUCT_ROOT = 'product-wiki';
export const SINK_DIR = 'product-wiki/product-requirements';
export const SAMPLE_DATA_DIR = 'product-wiki/sample-data';
export const INDEX_README = 'product-wiki/README.md';
export const SINK_README = 'product-wiki/product-requirements/README.md';

export const WIKI_PAGE = /^product-wiki\/.+\/README\.md$/;
export const WIKI_RESERVED = /^product-wiki\/(product-requirements|sample-data)\//;

// The pack takes no config — the product-wiki/ layout IS the standard. A config
// object on the pack entry is a settings mistake (probably a misremembered
// knob), surfaced once, by the layout check only (no cascade). Deliberately
// pack-local rather than a runner-level manifest flag: no other pack rejects
// config yet, and a core seam for it can subsume this when a second pack needs
// one. Known limit: riding a rule means rules:{"product-wiki-layout":"off"}
// silences the guard along with the check.
export function configGuard(ctx, rule) {
  const cfg = ctx.config?.packConfig?.['product-wiki'];
  if (cfg === undefined || cfg === null) return [];
  return [finding(rule, {
    file: '.claudinite-checks.json',
    what: 'product-wiki config: the pack takes no config — the product-wiki/ layout is the standard',
    fix: 'remove the "config" object from the product-wiki pack entry (to silence the freshness advisory use rules: {"product-wiki-freshness": "off"})',
  })];
}

