import { patternRule } from '../../../../engine/checks/helpers/pattern-rules.mjs';

export default patternRule({
  id: 'web-speech-capture-released-on-pagehide',
  severity: 'blocking',
  description: 'A repo that opens the microphone releases it on pagehide (bfcache-safe teardown), not just on implicit page unload',
  doc: 'skills/web-speech-io/SKILL.md',
  why: 'the browser does not reliably free the mic on implicit page teardown — a page frozen into the bfcache is suspended, not destroyed, so a live recognizer or getUserMedia stream keeps the device (and the recording indicator) on until a pagehide handler stops it',
  scanFiles: /\.(mjs|cjs|jsx?|tsx?)$/,
  excludeFiles: /^skills\/web-speech-io\//,
  repoWide: [{
    unlessSomeFileMatches: /addEventListener\s*\(\s*['"`]pagehide['"`]|\bonpagehide\b/,
    flagFilesMatching: [
      [/\bgetUserMedia\s*\(/],
      [/\b(webkitSpeechRecognition|SpeechRecognition)\b/, /\.start\s*\(/],
    ],
    neverFlagFiles: /\.(test|spec)\.[cm]?jsx?$|(^|\/)(__tests__|__mocks__|fixtures?)\//,
    what: 'opens the microphone (getUserMedia / a speech recognizer) but no source file releases the capture on `pagehide`',
    fix: 'in whichever page owns the capture, add `window.addEventListener("pagehide", …)` that aborts the recognizer and stops any getUserMedia tracks (and stop a preflight capture in a `finally`) — pagehide fires on real unload AND bfcache freeze, unlike beforeunload; if the capture lives in an offscreen document torn down via closeDocument, accept this rule for that file with a reason',
  }],
});
=====FILE packs/google-identity/skills/google-id-token-validation/token-audience.mjs
import { patternRule } from '../../../../engine/checks/helpers/pattern-rules.mjs';

const BARE_ISSUER = /https:\/\/accounts\.google\.com(?![\w/.-])/;
const ISSUER_WORD = /issuer/i;
const EMPTY_AUD = /aud(ience)?["']?\s*[:=]\s*(\[\s*\]|""|'')/i;
const WHAT = 'declares the Google accounts issuer with no (or an explicitly empty) expected audience';
const FIX = 'configure the validator\'s audience to your exact OAuth web-application client id, next to the issuer; never leave it unset';

export default patternRule({
  id: 'google-token-audience-pinned',
  severity: 'blocking',
  description: 'A validator config declaring the Google accounts issuer pins a non-empty expected audience',
  doc: 'skills/google-id-token-validation/SKILL.md',
  why: 'every Google-issued ID token shares that issuer, so signature + issuer alone accept a token minted for any Google OAuth client — the audience claim is the only thing that scopes a token to this app, and an unset audience is a full authentication bypass',
  scanFiles: /\.(ya?ml|json|toml|tf)$/,
  excludeFiles: /^skills\/google-id-token-validation\//,
  matchLines: [
    { match: BARE_ISSUER, whenFileMatches: ISSUER_WORD, unlessFileMatches: /\baud(ience)?\b/i, what: WHAT, fix: FIX },
    { match: BARE_ISSUER, whenFileMatches: [ISSUER_WORD, EMPTY_AUD], what: WHAT, fix: FIX },
  ],
});
=====FILE packs/google-identity/skills/google-id-token-validation/email-verified.mjs
import { patternRule } from '../../../../engine/checks/helpers/pattern-rules.mjs';

const CLAIMS_CONTEXT = /requestContext\s*\.\s*authorizer|jwt\.claims|verifyIdToken|jwtVerify/;

export default patternRule({
  id: 'google-token-email-verified',
  severity: 'blocking',
  description: 'Handler code trusts a Google ID token\'s email claim only when email_verified says so, compared as the authorizer delivers it',
  doc: 'skills/google-id-token-validation/SKILL.md',
  why: 'a Google ID token carries email regardless of verification — an action gated on the bare claim trusts an address Google has not verified; and behind an API Gateway JWT authorizer the claim arrives as a string, so a strict boolean compare silently rejects every genuinely-verified user',
  scanFiles: /\.(mjs|cjs|jsx?|tsx?|py)$/,
  excludeFiles: /(^|\/)(tests?|__tests__|spec)\/|\.(test|spec)\.|^skills\/google-id-token-validation\//,
  relevantWhen: { repoContains: /accounts\.google\.com|\.apps\.googleusercontent\.com/ },
  matchLines: [
    {
      match: /\b(claims|payload)\??\.email\b(?!_)|(claims|payload)\[['"]email['"]\]/,
      whenFileMatches: CLAIMS_CONTEXT,
      unlessFileMatches: /email_verified/,
      what: 'reads the token\'s email claim but never checks email_verified',
      fix: 'gate any identity-bearing action on the email_verified claim being true (behind an API Gateway JWT authorizer it arrives as the string \'true\')',
    },
    {
      match: /email_verified\W{0,4}\s*[!=]==\s*(true|false)\b/,
      whenFileMatches: [CLAIMS_CONTEXT, /requestContext/],
      what: 'compares email_verified to a boolean with strict equality behind an API Gateway authorizer',
      fix: 'compare against the string \'true\' (or coerce) — the authorizer stringifies claims, so a strict boolean compare rejects every verified user',
    },
  ],
});
=====FILE packs/grow_with_claudinite/skills/unattended-agents/in-session-github-access.mjs
import { patternRule } from '../../../../engine/checks/helpers/pattern-rules.mjs';

const FIX = 'reach GitHub through the session’s injected MCP-backed I/O (a gh(path) reader for reads, a semantic io object for writes); move any work that needs an account-wide credential into a workflow_dispatch-only executor';

export default patternRule({
  id: 'in-session-github-access',
  severity: 'blocking',
  description: 'In-session routine code reaches GitHub through the MCP tools, not a REST client + GITHUB_TOKEN',
  doc: 'skills/unattended-agents/SKILL.md',
  why: 'a routine runs in an MCP-only session with no shell GitHub REST credential; a REST client / GITHUB_TOKEN in its own steps cannot authenticate there — that belongs in a workflow_dispatch-only CI executor',
  scanFiles: /^(routines|migrations)\/.*\.mjs$/,
  excludeFiles: /\.test\.mjs$/,
  skipLinesMatching: /^\s*(\/\/|\*|\/\*)/,
  matchLines: [
    {
      match: /process\.env\.(GITHUB_TOKEN|GH_TOKEN|FLEET_GITHUB_TOKEN)/,
      what: 'reads a GitHub REST token from the environment — in-session routine code has no REST credential',
      fix: FIX,
    },
    {
      match: /\bmakeGh\s*\(|from\s+['"][^'"]*\bfleet-api/,
      what: 'uses the REST client (makeGh / fleet-api) — in-session routine code has no REST credential',
      fix: FIX,
    },
    {
      match: /['"`]https?:\/\/api\.github\.com/,
      what: 'targets the GitHub REST API (api.github.com) directly — in-session routine code has no REST credential',
      fix: FIX,
    },
  ],
});

