1	import { readdirSync, existsSync } from 'node:fs';
2	import { join, dirname, resolve } from 'node:path';
3	import { fileURLToPath, pathToFileURL } from 'node:url';
4	import { validateManifest, normalizeManifest } from './pack-schema.mjs';
5	
6	// This module lives at <canon>/engine/pack_loader/; the packs it scans at <canon>/packs/.
7	const canonRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
8	const packsDir = join(canonRoot, 'packs');
9	
10	// A repo's own packs live at <root>/.claudinite/local/packs/<name>/ — tracked
11	// project content, discovered and run by the same engine as the mounted canon
12	// packs, and sitting at the same uniform depth as the shared mount
13	// (.claudinite/*/packs/). This is the canonical subdir relative to a consumer's
14	// checkout root. The pre-2026-07 layout put them one level up at
15	// .claudinite/local_packs/; discovery scans BOTH roots until the rename has
16	// propagated fleet-wide (Phase 4 drops the legacy scan), so a repo that hasn't
17	// been git-mv'd yet still loads.
18	export const LOCAL_PACKS_SUBDIR = join('.claudinite', 'local', 'packs');
19	export const LEGACY_LOCAL_PACKS_SUBDIR = join('.claudinite', 'local_packs');
20	export const localPacksDir = (root) => join(resolve(root), LOCAL_PACKS_SUBDIR);
21	export const legacyLocalPacksDir = (root) => join(resolve(root), LEGACY_LOCAL_PACKS_SUBDIR);
22	
23	// Where a consumer materializes the vendored canon (vendoring/DESIGN.md): the
24	// corpus mirrored at canon-relative paths under this subdir. Tracked files in
25	// the interim; the planned future is a git submodule mounted at this same path
26	// — which is why nothing consumer-owned (local_packs/ above) lives inside it.
27	export const SHARED_SUBDIR = join('.claudinite', 'shared');
28	
29	// The full pack directory — the generated catalog of every canon pack a repo
30	// can adopt, rendered from the manifests by its drift test and vendored into
31	// every mount regardless of declaration (a consumer holds only its declared
32	// packs, so without this file a member session has no view of what else it
33	// could add). One definition of the path: the vendor-set computation includes
34	// it, the prose injector points sessions at it.
35	export const PACK_DIRECTORY_FILE = 'packs/directory.GENERATED.md';
36	
37	// Load a directory of `<name>/pack.mjs` manifests, isolating each import so one
38	// broken manifest can't sink the rest (a consumer-authored local pack.mjs must
39	// never disable every other pack's prose/checks/skills). Each loaded pack is
40	// stamped with `dir` (its own directory — prose and bundled skills resolve off
41	// this, so a pack's files never have to sit under a single shared root) and
42	// `local` (whether it came from a consumer's local_packs). A pack's skills live
43	// in its own tree — `<pack>/skills/<skill>/` is the one bundled-skill shape,
44	// canon and local alike (#385: a skill rides exactly one pack; there is no
45	// separate skills collection to own or cross-declare). A bundled skill's
46	// checks.mjs is gathered onto `skillChecks` and run by the runner only when the
47	// pack is active.
48	// A pack's declared adoption questions, validated: `questions` (an optional
49	// manifest field any pack may carry) must be an array of { id, prompt, distill? }
50	// with non-empty string ids and prompts, ids unique within the pack. A malformed
51	// entry is reported and skipped — one bad question must not mute the pack's valid
52	// ones (the registry's fail-soft posture). This is generic manifest-shape
53	// validation, so it lives with pack loading (scanPackDir reports the errors as
54	// load faults); the interview machinery imports it to read the valid questions.
55	export function packQuestions(pack) {
56	  const questions = [];
57	  const errors = [];
58	  const src = pack.questions;
59	  if (src === undefined || src === null) return { questions, errors };
60	  if (!Array.isArray(src)) {
61	    errors.push({
62	      what: `the "${pack.id}" pack declares a non-array "questions"`,
63	      fix: 'make questions an array of { id, prompt } entries',
64	    });
65	    return { questions, errors };
66	  }
67	  const seen = new Set();
68	  for (const q of src) {
69	    if (q === null || typeof q !== 'object' || typeof q.id !== 'string' || !q.id
70	      || typeof q.prompt !== 'string' || !q.prompt) {
71	      errors.push({
72	        what: `the "${pack.id}" pack declares a malformed question ${JSON.stringify(q)}`,
73	        fix: 'give each question a non-empty string "id" and "prompt"',
74	      });
75	      continue;
76	    }
77	    if (seen.has(q.id)) {
78	      errors.push({
79	        what: `the "${pack.id}" pack declares question id "${q.id}" twice`,
80	        fix: 'question ids must be unique within the pack — rename one',
81	      });
82	      continue;
83	    }
84	    seen.add(q.id);
85	    questions.push(q);
86	  }
87	  return { questions, errors };
88	}
89	
90	async function scanPackDir(dir, { local, subdir }, errors) {
91	  const out = [];
92	  if (!existsSync(dir)) return out;
93	  const label = subdir ?? (local ? LOCAL_PACKS_SUBDIR : 'packs');
94	  // A non-directory (or unreadable path) at a scan root is a fault to REPORT, not
95	  // a crash — the whole point of discovery being fail-soft is a diagnostic instead
96	  // of a dead runner (the SessionStart hooks fail soft; the runner surfaces it).
97	  let names;
98	  try {
99	    names = readdirSync(dir, { withFileTypes: true })
100	      .filter((d) => d.isDirectory()).map((d) => d.name).sort();
101	  } catch (e) {
102	    errors.push({
103	      what: `${label} is not a readable directory: ${e.message}`,
104	      fix: `make ${label} a directory (or remove it)`,
105	      dir,
106	    });
107	    return out;
108	  }
109	  for (const name of names) {
110	    const packDir = join(dir, name);
111	    const rel = local ? `${label}/${name}` : `packs/${name}`;
112	    const manifest = join(packDir, 'pack.mjs');
113	    if (!existsSync(manifest)) continue;
114	    let mod;
115	    try {
116	      mod = (await import(pathToFileURL(manifest).href)).default;
117	    } catch (e) {
118	      errors.push({
119	        what: `the pack in ${rel} failed to load: ${e.message}`,
120	        fix: `fix pack.mjs in ${rel}, or remove the pack`,
121	        dir: packDir,
122	      });
123	      continue;
124	    }
125	    if (!mod || typeof mod.id !== 'string') {
126	      errors.push({
127	        what: `the pack in ${rel} has no string "id" default export`,
128	        fix: 'export default { id: "<name>", ... } from its pack.mjs',
129	        dir: packDir,
130	      });
131	      continue;
132	    }
133	    // A local pack's id must equal its directory name. The engine activates a pack
134	    // by its exported id, but the fleet planner reads a local pack's daily tasks by
135	    // directory name (it never imports pack.mjs), so a mismatch would silently
136	    // diverge — the engine runs the pack while the fleet skips its task. Require
137	    // dir == id so the two can never disagree (the canon convention, enforced here
138	    // for local packs).
139	    if (local && mod.id !== name) {
140	      errors.push({
141	        what: `the local pack in ${rel} exports id "${mod.id}" but its directory is "${name}"`,
142	        fix: `rename the directory to "${mod.id}", or set the pack's id to "${name}" — a local pack's id must match its directory name`,
143	        dir: packDir,
144	      });
145	      continue;
146	    }
147	    // A malformed `questions` manifest field is a load fault like any other —
148	    // reported here so the runner surfaces it pack-agnostically, no interview
149	    // import needed (the pack owns the interview HYGIENE check; the engine owns
150	    // the manifest-shape validation).
151	    for (const e of packQuestions(mod).errors) errors.push({ ...e, dir: packDir });
152	    // The rest of the manifest against the spec (pack-schema.mjs). REPORTED, not
153	    // fatal: a pack whose declaration is incomplete still loads and still runs
154	    // its checks — silently disabling a repo's own rules is a worse failure than
155	    // the one being reported, and the blocking config error is what gets it fixed.
156	    for (const e of validateManifest(mod, { label: `the pack in ${rel}`, skillDirs: skillDirNames(packDir) })) {
157	      errors.push({ ...e, dir: packDir });
158	    }
159	    const pack = { ...normalizeManifest(mod), dir: packDir, local };
160	    pack.skillChecks = await scanSkillChecks(packDir, errors);
161	    out.push(pack);
162	  }
163	  return out;
164	}
165	
166	// The skill directory names a pack bundles — the tree side of the manifest's
167	// `skills` declaration, which the spec holds to it in both directions. Absent or
168	// unreadable skills/ reads as none: scanSkillChecks reports the unreadable case,
169	// and the spec must not turn one broken directory into a wall of phantom findings.
170	function skillDirNames(packDir) {
171	  const skillsRoot = join(packDir, 'skills');
172	  if (!existsSync(skillsRoot)) return [];
173	  try {
174	    return readdirSync(skillsRoot, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
175	  } catch {
176	    return [];
177	  }
178	}
179	
180	// A pack's skill-owned checks: any <pack>/skills/<skill>/checks.mjs (default
181	// export = an array of rules). Isolated per import; run gated by the owning
182	// pack being active, exactly like the pack's own rules — a skill is pack
183	// content, so its checks ride the pack's activation.
184	async function scanSkillChecks(packDir, errors) {
185	  const rules = [];
186	  const skillsRoot = join(packDir, 'skills');
187	  if (!existsSync(skillsRoot)) return rules;
188	  let names;
189	  try {
190	    names = readdirSync(skillsRoot, { withFileTypes: true })
191	      .filter((d) => d.isDirectory()).map((d) => d.name).sort();
192	  } catch (e) {
193	    errors.push({ what: `${LOCAL_PACKS_SUBDIR} skills path is not a readable directory: ${e.message}`, fix: 'make the pack\'s skills/ a directory (or remove it)', dir: skillsRoot });
194	    return rules;
195	  }
196	  for (const name of names) {
197	    const manifest = join(skillsRoot, name, 'checks.mjs');
198	    if (!existsSync(manifest)) continue;
199	    try {
200	      rules.push(...(await import(pathToFileURL(manifest).href)).default);
201	    } catch (e) {
202	      errors.push({ what: `local skill check ${name}/checks.mjs failed to load: ${e.message}`, fix: 'fix or remove the skill\'s checks.mjs', dir: join(skillsRoot, name) });
203	    }
204	  }
205	  return rules;
206	}
207	
208	// Discover every pack structurally — canon `packs/<name>/pack.mjs` always, plus a
209	// consumer's own `<localRoot>/.claudinite/local_packs/<name>/pack.mjs` when a
210	// localRoot is given (the repo under test / the session's project root). No
211	// registry list to maintain — dropping a directory in adds it. Returns the packs
212	// plus any load-time `errors` (a broken manifest, a missing id, an id collision);
213	// the runner surfaces those as blocking `config` findings, the fail-soft
214	// SessionStart hooks just skip the offending pack. Canon is scanned first, so a
215	// local pack may not shadow a canon id — the collision is reported and the local
216	// one dropped (a consumer extends the canon, never silently overrides it).
217	export async function discoverPacks({ localRoot } = {}) {
218	  const errors = [];
219	  const canon = await scanPackDir(packsDir, { local: false }, errors);
220	  // Scan BOTH local roots (canonical .claudinite/local/packs and the legacy
221	  // .claudinite/local_packs) so a repo mid-rename still loads; a pack present in
222	  // both would trip the id-collision guard below, which is the desired signal.
223	  const local = localRoot
224	    ? [
225	      ...await scanPackDir(localPacksDir(localRoot), { local: true, subdir: LOCAL_PACKS_SUBDIR }, errors),
226	      ...await scanPackDir(legacyLocalPacksDir(localRoot), { local: true, subdir: LEGACY_LOCAL_PACKS_SUBDIR }, errors),
227	    ]
228	    : [];
229	  const byId = new Map();
230	  const packs = [];
231	  for (const pack of [...canon, ...local]) {
232	    if (byId.has(pack.id)) {
233	      const first = byId.get(pack.id);
234	      errors.push({
235	        what: `pack id "${pack.id}" is declared twice — by ${first.local ? 'a local pack' : 'the canon'} and ${pack.local ? 'a local pack' : 'the canon'}`,
236	        fix: `rename the local pack in ${LOCAL_PACKS_SUBDIR}/ — a local pack id must be unique and may not shadow a canon pack`,
237	        dir: pack.dir,
238	      });
239	      continue;
240	    }
241	    byId.set(pack.id, pack);
242	    packs.push(pack);
243	  }
244	  return { packs, errors };
245	}
246	
247	// The pack list alone — the shape every non-runner caller wants. Canon-only when
248	// no localRoot is given (the fleet planner and the declaration-writing backfill
249	// run in the canon checkout and read member declarations over the API, not from
250	// local disk). A broken/duplicate pack is simply absent here; the runner's
251	// discoverPacks surfaces the diagnostic.
252	export async function loadPacks(opts) {
253	  return (await discoverPacks(opts)).packs;
254	}
255	
256	// A local pack's canonical declaration token is namespaced `local/<id>` —
257	// self-documenting in .claudinite-checks.json (a reader sees at a glance the
258	// pack lives in the repo's own tree under .claudinite/local/, and a canon id can
259	// never be claimed by accident; the discoverPacks shadow guard stays as the
260	// backstop). Both the pre-rename `local_packs/<id>` form and the bare id remain
261	// accepted while the fleet migrates (baselining's normalization + the
262	// local-pack-namespace migration track convergence), so packEntryId strips
263	// whichever prefix is present and every id comparison happens on the bare id.
264	export const LOCAL_DECL_PREFIX = 'local/';
265	export const LEGACY_LOCAL_DECL_PREFIX = 'local_packs/';
266	const stripLocalPrefix = (id) => {
267	  for (const prefix of [LOCAL_DECL_PREFIX, LEGACY_LOCAL_DECL_PREFIX]) {
268	    if (id.startsWith(prefix)) return id.slice(prefix.length);
269	  }
270	  return id;
271	};
272	
273	// The writer-side inverse: the token a declaration writer records for a pack —
274	// namespaced (canonical form) for a local pack, the bare id for a canon one.
275	export const declTokenFor = (pack) =>
276	  pack.local ? LOCAL_DECL_PREFIX + pack.id : pack.id;
277	
278	// A `packs` declaration entry is either a plain id string or an entry object
279	// `{ id, config?, rules?, accept?, via? }` carrying that pack's own settings
280	// (see engine/checks/README.md). This is the one id-extractor every reader shares, so
281	// raw-JSON consumers (the SessionStart hooks, the fleet signal probe) and the
282	// engine agree on both shapes — and on both declaration forms: it returns the
283	// BARE pack id, stripping a `local_packs/` namespace where one is declared.
284	// Returns undefined for a malformed entry.
285	export const packEntryId = (entry) =>
286	  typeof entry === 'string'
287	    ? stripLocalPrefix(entry)
288	    : entry !== null && typeof entry === 'object' && typeof entry.id === 'string'
289	      ? stripLocalPrefix(entry.id)
290	      : undefined;
291	
292	// No pack is active by default. Activation is exactly the project's declaration
293	// in .claudinite-checks.json (bootstrap's --init seeds the default-on packs).
294	export const isActive = (pack, config) =>
295	  (config.packs ?? []).some((entry) => packEntryId(entry) === pack.id);
296	
297	// The MOUNTED SKILL SET: the union of the given packs' bundled skills, as a
298	// Map(name -> the skill's directory). A bundled skill is `<pack>/skills/<name>/`
299	// carrying a SKILL.md — the one shape, canon and local alike (#385). The packs are
300	// taken in the caller's order and the FIRST occurrence of a name wins, so a caller
301	// passing canon packs before local ones resolves a shared name to canon.
302	//
303	// One definition, two readers: the SessionStart mount hook (mount-skills.mjs) turns
304	// it into `.claude/skills/` symlinks, and the usage fold asks it which skill names a
305	// typed `/command` could possibly be. The mounts themselves are gitignored session
306	// state, so anything reasoning about "what is mounted here" must ask the registry —
307	// this function — and never the mount directory.
308	export function bundledSkillSources(packs) {
