    "id": "google-token-audience-pinned",
    "severity": "blocking",
    "failureMessage": "every Google-issued ID token shares that issuer, so signature + issuer alone accept a token minted for any Google OAuth client — the audience claim is the only thing that scopes a token to this app, and an unset audience is a full authentication bypass",
    "scanFiles": "/\\.(ya?ml|json|toml|tf)$/",
    "excludeFiles": "/^skills\\/google-id-token-validation\\//",
    "matchLines": [
      {
        "match": "/https:\\/\\/accounts\\.google\\.com(?![\\w/.-])/",
        "whenFileMatches": "/issuer/i",
        "unlessFileMatches": "/\\baud(ience)?\\b/i",
        "what": "declares the Google accounts issuer with no (or an explicitly empty) expected audience",
        "fix": "configure the validator's audience to your exact OAuth web-application client id, next to the issuer; never leave it unset"
      },
      {
        "match": "/https:\\/\\/accounts\\.google\\.com(?![\\w/.-])/",
        "whenFileMatches": ["/issuer/i", "/aud(ience)?[\"']?\\s*[:=]\\s*(\\[\\s*\\]|\"\"|'')/i"],
        "what": "declares the Google accounts issuer with no (or an explicitly empty) expected audience",
        "fix": "configure the validator's audience to your exact OAuth web-application client id, next to the issuer; never leave it unset"
      }
    ]
  },
  {
    "id": "google-token-email-verified",
    "severity": "blocking",
    "failureMessage": "a Google ID token carries email regardless of verification — an action gated on the bare claim trusts an address Google has not verified; and behind an API Gateway JWT authorizer the claim arrives as a string, so a strict boolean compare silently rejects every genuinely-verified user",
    "scanFiles": "/\\.(mjs|cjs|jsx?|tsx?|py)$/",
    "excludeFiles": "/(^|\\/)(tests?|__tests__|spec)\\/|\\.(test|spec)\\.|^skills\\/google-id-token-validation\\//",
    "relevantWhen": { "repoContains": "/accounts\\.google\\.com|\\.apps\\.googleusercontent\\.com/" },
    "matchLines": [
      {
        "match": "/\\b(claims|payload)\\??\\.email\\b(?!_)|(claims|payload)\\[['\"]email['\"]\\]/",
        "whenFileMatches": "/requestContext\\s*\\.\\s*authorizer|jwt\\.claims|verifyIdToken|jwtVerify/",
        "unlessFileMatches": "/email_verified/",
        "what": "reads the token's email claim but never checks email_verified",
        "fix": "gate any identity-bearing action on the email_verified claim being true (behind an API Gateway JWT authorizer it arrives as the string 'true')"
      },
      {
        "match": "/email_verified\\W{0,4}\\s*[!=]==\\s*(true|false)\\b/",
        "whenFileMatches": [
          "/requestContext\\s*\\.\\s*authorizer|jwt\\.claims|verifyIdToken|jwtVerify/",
          "/requestContext/"
        ],
        "what": "compares email_verified to a boolean with strict equality behind an API Gateway authorizer",
        "fix": "compare against the string 'true' (or coerce) — the authorizer stringifies claims, so a strict boolean compare rejects every verified user"
      }
    ]
  }
]

