27	 * commits all share one timestamp is ambiguous to git where dates break ties — most
28	 * visibly `merge-base`, which returns one of several equally-good answers — so a test
29	 * that depends on the shape of the graph pins the dates instead of racing the clock.
30	 */
31	export function gitDated(root, epochSeconds, ...args) {
32	  const stamp = `${epochSeconds} +0000`;
33	  const r = spawnSync('git', args, {
34	    cwd: root, encoding: 'utf8',
35	    env: { ...GIT_ENV, GIT_AUTHOR_DATE: stamp, GIT_COMMITTER_DATE: stamp },
36	  });
37	  if (r.status !== 0) throw new Error(`git ${args.join(' ')} failed: ${r.stderr}`);
