50	 * `changed` files committed on top (message `commitMsg`). Mirrors the runner's
51	 * real scoping model — merge-base with `main` — without needing a remote.
52	 */
53	export function makeRepo({ base = {}, changed = {}, commitMsg = 'change Refs #1', uncommitted = {} }) {
54	  const root = mkdtempSync(join(tmpdir(), 'claudinite-checks-'));
55	  git(root, 'init', '-q', '-b', 'main');
56	  writeFiles(root, { 'README.md': 'seed\n', ...base });
57	  git(root, 'add', '-A');
58	  git(root, 'commit', '-q', '-m', 'seed');
59	  git(root, 'checkout', '-q', '-b', 'feature');
60	  if (Object.keys(changed).length) {
61	    writeFiles(root, changed);
62	    git(root, 'add', '-A');
63	    git(root, 'commit', '-q', '-m', commitMsg);
64	  }
65	  writeFiles(root, uncommitted);
66	  return root;
67	}
