87	  // repo's .git/* while this recursive rmdir walks it, so the delete intermittently
88	  // throws ENOTEMPTY. rmSync retries that error class with linear backoff — without it
89	  // a healthy run reddens CI (seen on PR #255).
90	  rmSync(root, { recursive: true, force: true, maxRetries: 3, retryDelay: 50 });
